/bin/bash -lc "cat >> .codex-role-output/checkpoint.md <<'EOF'

Root cause: "'`consts/mime_types.go` registers mappings at package init and derives `consts.LosslessFormats` from hardcoded maps. `conf.Load` runs hooks after config fields are set. `resources.FS()` merges embedded resources with `DataFolder/resources`, so a `resources/mime_types.yaml` resource can provide bundled defaults and operator overrides. UI currently reads the consts list.

Hypothesis: moving registration into a `mime` startup hook that reads `resources.FS()` will make both MIME lookup and the UI list reflect runtime YAML. Test with an override containing a custom extension and lossless entry.
EOF
mkdir -p mime
cat > mime/mime_test.go <<'"'EOF'
package mime

import (
	\"mime\"
	\"os\"
	\"path/filepath\"
	\"reflect\"
	\"testing\"

	\"github.com/navidrome/navidrome/conf\"
	\"github.com/spf13/viper\"
)

func TestLoadConfiguredMIMETypes(t *testing.T) {
	dataFolder := t.TempDir()
	resourceFolder := filepath.Join(dataFolder, \"resources\")
	if err := os.Mkdir(resourceFolder, 0755); err "'!= nil {
		t.Fatal(err)
	}
	config := "types:'"\\n  .custom: audio/x-custom\\nlossless:\\n  - .custom\\n\"
	if err := os.WriteFile(filepath.Join(resourceFolder, \"mime_types.yaml\"), []byte(config), 0644); err "'!= nil {
		t.Fatal(err)
	}
	viper.Set("datafolder", dataFolder)
	defer viper.Set("datafolder", ".")
	conf.Load()

	if got := mime.TypeByExtension(".custom"); got != "audio/x-custom" {
		t.Errorf("custom MIME type = %q, want audio/x-custom", got)
	}
	if !reflect.DeepEqual(LosslessFormats, []string{"custom"}) {
		t.Errorf("lossless formats = %v, want [custom]", LosslessFormats)
	}
	if got := mime.TypeByExtension(".js"); got != "text/javascript" {
		t.Errorf("JavaScript MIME type = %q", got)
	}
	if got := mime.TypeByExtension(".css"); got != "text/css" {
		t.Errorf("CSS MIME type = %q", got)
	}
}
EOF
GOPROXY=off go test ./mime -run TestLoadConfiguredMIMETypes -count=1'
